export const paymentProofs = defineTable(
  'payment_proofs',
  {
    module: 'M21',
    scope: 'branch',
    household: true,
    householdRule: { read: true, insert: { status: 'submitted' } },
  },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    familyId: uuid()
      .references((): AnyPgColumn => families.id)
      .notNull(),
    challanNo: text(),
    amount: paisa().notNull(),
    /** not in the future */
    paidOn: dateStr().notNull(),
    /** the bank's transaction id */
    reference: text(),
    fileId: uuid()
      .references((): AnyPgColumn => files.id)
      .notNull(),
    submittedBy: uuid()
      .references((): AnyPgColumn => profiles.id)
      .notNull(),
    status: enumText(paymentProofStatuses).notNull().default('submitted'),
    verifiedBy: uuid().references((): AnyPgColumn => profiles.id),
    verifiedAt: timestamptz(),
    rejectReason: text(),
    /** set when verified */
    paymentId: uuid().references((): AnyPgColumn => feePayments.id),
  },
  (t) => [positive('payment_proofs', t.amount)],
);

/** What was said when the school chased a family for dues. */
export const feeFollowups = defineTable(
  'fee_followups',
  { module: 'M21', scope: 'branch' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    familyId: uuid()
      .references((): AnyPgColumn => families.id)
      .notNull(),
    channel: enumText(feeFollowupChannels).notNull(),
    outcome: enumText(feeFollowupOutcomes).notNull(),
    /** required for `promised` */
    promisedDate: dateStr(),
    promisedAmount: paisa(),
    note: text(),
    doneBy: uuid()
      .references((): AnyPgColumn => profiles.id)
      .notNull(),
    doneAt: timestamptz().notNull(),
  },
  (t) => [
    check(
      'fee_followups_promised_date_needed',
      sql`${t.outcome} <> 'promised' or ${t.promisedDate} is not null`,
    ),
    nonNegative('fee_followups', t.promisedAmount),
  ],
);
